    function otdShareMonth() {
        var MN = ['January','February','March','April','May','June','July','August','September','October','November','December'];
        var SL = { mlb:'MLB', nba:'NBA', nhl:'NHL', nfl:'NFL', wnba:'WNBA', golf:'Golf', ufc:'UFC', mma:'UFC', ncaaf:'CFB', ncaam:'CBB', ncaabb:'CBB', soccer:'Soccer', fc:'Soccer', ucl:'UCL', epl:'EPL' };
        var monthKey = otdCalYear + '-' + String(otdCalMonth + 1).padStart(2, '0');
        var totalRax = 0, claimDays = 0, sportTotals = {}, playerTotals = {}, playerBestEntry = {};
        Object.keys(otdDateMap).forEach(function(dk) {
            if (!dk.startsWith(monthKey + '-')) return;
            var entries = otdDateMap[dk];
            if (!entries.length) return;
            var dayHadRealClaim = false;
            entries.forEach(function(e) {
                var pl = e.player;
                if (!pl || pl.isAdded) return; // skip simulated passes
                var rax = e.rax || 0;
                // If the user changed rarity, recalculate rax using the original multiplier
                if (pl._origLevel !== undefined && pl._origLevel !== pl.level) {
                    var currMult = pl.multiplier ? parseFloat(pl.multiplier) : 0;
                    var origMult = pl._origMultiplier ? parseFloat(pl._origMultiplier) : currMult;
                    rax = (currMult > 0) ? Math.round(rax / currMult * origMult) : rax;
                }
                if (!rax) return;
                dayHadRealClaim = true;
                totalRax += rax;
                var sp = pl.sport || 'unknown';
                sportTotals[sp] = (sportTotals[sp] || 0) + rax;
                var pk = (pl.id || '?') + '|' + sp + '|' + (pl.name || '?');
                playerTotals[pk] = (playerTotals[pk] || 0) + rax;
                if (!playerBestEntry[pk] || rax > (playerBestEntry[pk].rax || 0)) playerBestEntry[pk] = e;
            });
            if (dayHadRealClaim) claimDays++;
        });
        if (!totalRax) { otdCopyToast('No earnings this month'); return; }
        var avg = claimDays > 0 ? Math.round(totalRax / claimDays) : 0;
        // Yearly total — sum all entries in otdCalYear across all months
        var yearlyTotal = 0;
        var yearPrefix = String(otdCalYear) + '-';
        Object.keys(otdDateMap).forEach(function(dk) {
            if (!dk.startsWith(yearPrefix)) return;
            otdDateMap[dk].forEach(function(e) {
                var pl = e.player;
                if (!pl || pl.isAdded) return;
                var rax = e.rax || 0;
                if (pl._origLevel !== undefined && pl._origLevel !== pl.level) {
                    var cm = pl.multiplier ? parseFloat(pl.multiplier) : 0;
                    var om = pl._origMultiplier ? parseFloat(pl._origMultiplier) : cm;
                    rax = cm > 0 ? Math.round(rax / cm * om) : rax;
                }
                yearlyTotal += rax;
            });
        });
        var topKey = Object.keys(playerTotals).sort(function(a, b) { return playerTotals[b] - playerTotals[a]; })[0];
        var topParts = topKey ? topKey.split('|') : [];
        var sportLines = Object.keys(sportTotals).sort(function(a, b) { return sportTotals[b] - sportTotals[a]; }).map(function(s) {
            return (OTD_SPORT_EMOJI[s] || '🎴') + ' ' + (SL[s] || s.toUpperCase()) + ': ' + sportTotals[s].toLocaleString() + ' Rax';
        }).join('\n');
        var username = otdSelectedUser ? otdSelectedUser.username : '';
        var lines = [
            'RaxEdge:  ' + MN[otdCalMonth] + ' ' + otdCalYear + ' - OTD Recap',
            '-',
            '💰 Total Rax: ' + totalRax.toLocaleString(),
            '📊 Avg/day: ' + avg.toLocaleString() + ' Rax',
            '📅 ' + otdCalYear + ' Total: ' + yearlyTotal.toLocaleString() + ' Rax',
            '-',
            'Sports Breakdown:',
            sportLines,
        ];
        if (topParts.length === 3) {
            lines.push('🏆 ' + topParts[2] + ' (' + (SL[topParts[1]] || topParts[1]) + ') — ' + playerTotals[topKey].toLocaleString() + ' Rax');
            var topEntry = playerBestEntry[topKey];
            var topId = parseInt(topParts[0], 10);
            var topSport = topParts[1];
            var topEt = (topEntry && topEntry.player && topEntry.player.entityType) || 'player';
            var topPassId = topEntry && topEntry.player && topEntry.player.passId ? parseInt(topEntry.player.passId, 10) : 0;
            var cardUrl = topPassId
                ? 'https://www.realapp.com/' + rsUrlHash(18, RS_SPORT_CODE[topSport] || 0, 0, topPassId)
                : rsEntityUrl(topEt, topSport, topId);
            var bsIdNum = topEntry && topEntry.bsId ? parseInt(topEntry.bsId, 10) : 0;
            var perfUrl = bsIdNum > 0 ? 'https://www.realapp.com/' + rsUrlHash(14, 0, 0, bsIdNum) : '';
            lines.push('🃏 ' + cardUrl + (perfUrl ? ' 📈 ' + perfUrl : ''));
        }
        lines.push('-');
        if (username) lines.push('🔗 https://raxedge.com/otd/' + username);
        var msg = lines.join('\n');
        navigator.clipboard.writeText(msg).then(function() { otdCopyToast('Copied!'); }).catch(function() {
            var ta = document.createElement('textarea'); ta.value = msg; ta.style.cssText = 'position:fixed;opacity:0';
            document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
            otdCopyToast('Copied!');
        });
    }
    function otdCopyToast(msg) {
        var el = document.getElementById('otd-copy-toast');
        if (!el) {
            el = document.createElement('div'); el.id = 'otd-copy-toast';
            el.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#22c55e;color:#fff;font-size:13px;font-weight:700;padding:8px 20px;border-radius:20px;z-index:9999;pointer-events:none;font-family:var(--sans);transition:opacity .3s';
            document.body.appendChild(el);
        }
        el.textContent = msg; el.style.opacity = '1';
        clearTimeout(el._t); el._t = setTimeout(function() { el.style.opacity = '0'; }, 2000);
    }
